# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">DOĞRUSAL FONKSİYONLARDA ÖTELEME VE DİKEY ÖLÇEKLEME: g(x) = a·f(x ± r) ± k</text>\n  <rect x="25" y="42" width="320" height="200" rx="10" fill="#ffffff" stroke="#cbd5e1" stroke-width="2"/>\n  <line x1="45" y1="145" x2="325" y2="145" stroke="#64748b" stroke-width="1.5"/>\n  <text x="330" y="149" font-size="11" font-weight="bold" fill="#334155">x</text>\n  <line x1="185" y1="225" x2="185" y2="55" stroke="#64748b" stroke-width="1.5"/>\n  <text x="181" y="50" font-size="11" font-weight="bold" fill="#334155">y</text>\n  <line x1="105" y1="225" x2="265" y2="65" stroke="#94a3b8" stroke-width="2" stroke-dasharray="5,3"/>\n  <text x="275" y="75" font-size="11" font-weight="bold" fill="#475569">f(x) = x</text>\n  <line x1="75" y1="215" x2="235" y2="55" stroke="#2563eb" stroke-width="2.5"/>\n  <text x="115" y="88" font-size="11" font-weight="bold" fill="#1d4ed8">g₁(x) = x + 3 (+y öteleme)</text>\n  <line x1="145" y1="60" x2="225" y2="220" stroke="#dc2626" stroke-width="2.5"/>\n  <text x="232" y="205" font-size="11" font-weight="bold" fill="#dc2626">g₂(x) = -2x + 1</text>\n  <rect x="360" y="42" width="315" height="200" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="517" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">DÖNÜŞÜM PARAMETRELERİ (a, r, k)</text>\n  <text x="377" y="94" font-size="11.5" font-weight="bold" fill="#1e3a8a">• Düşey Öteleme (±k): f(x) + k</text>\n  <text x="387" y="111" font-size="10.5" fill="#334155">k &gt; 0 ise y ekseninde k birim yukarı; k &lt; 0 ise aşağı.</text>\n  <text x="377" y="135" font-size="11.5" font-weight="bold" fill="#1e3a8a">• Yatay Öteleme (±r): f(x - r)</text>\n  <text x="387" y="152" font-size="10.5" fill="#334155">f(x - r) grafiği r birim SAĞA; f(x + r) ise r birim SOLA!</text>\n  <text x="377" y="176" font-size="11.5" font-weight="bold" fill="#1e3a8a">• Eğim ve Ölçekleme (a): a · f(x)</text>\n  <text x="387" y="193" font-size="10.5" fill="#334155">|a| &gt; 1 ise dikleşir; 0 &lt; |a| &lt; 1 ise yataylaşır;</text>\n  <text x="387" y="209" font-size="10.5" font-weight="bold" fill="#dc2626">a &lt; 0 ise x eksenine göre simetri (azalan doğru) olur.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">g(x) = ax + b FONKSİYONUNUN NİTEL ÖZELLİKLERİ VE İŞARET İNCELEMESİ</text>\n  <rect x="25" y="42" width="315" height="200" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="182" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">EKSEN KESİM NOKTALARI VE İŞARET</text>\n  <text x="42" y="92" font-size="11.5" font-weight="bold" fill="#14532d">• y Eksenini Kestiği Nokta (x = 0):</text>\n  <text x="52" y="110" font-size="11" fill="#334155">g(0) = b  →  (0, b) noktası</text>\n  <text x="42" y="135" font-size="11.5" font-weight="bold" fill="#14532d">• Sıfırı / Kökü (x Eksenini Kestiği Nokta, y = 0):</text>\n  <text x="52" y="153" font-size="11" font-weight="bold" fill="#15803d">ax + b = 0  →  x₀ = -b / a   ((-b/a, 0) noktası)</text>\n  <text x="42" y="178" font-size="11.5" font-weight="bold" fill="#14532d">• İşaret Tablosu (a &gt; 0, Artan Doğru İçin):</text>\n  <text x="52" y="196" font-size="11" fill="#334155">- x &gt; -b/a aralığında: g(x) &gt; 0 (Pozitif, x üstünde)</text>\n  <text x="52" y="214" font-size="11" fill="#334155">- x &lt; -b/a aralığında: g(x) &lt; 0 (Negatif, x altında)</text>\n  <rect x="360" y="42" width="315" height="200" rx="10" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="517" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#854d0e">BİRE BİRLİK VE MAKSİMUM - MİNİMUM</text>\n  <text x="377" y="92" font-size="11.5" font-weight="bold" fill="#713f12">• Bire Birlik (a ≠ 0):</text>\n  <text x="387" y="110" font-size="10.5" fill="#334155">Her x₁ ≠ x₂ için g(x₁) ≠ g(x₂) olduğundan tüm</text>\n  <text x="387" y="126" font-size="10.5" fill="#334155">doğrusal fonksiyonlar (a ≠ 0) bire birdir (Yatay doğru</text>\n  <text x="387" y="142" font-size="10.5" fill="#334155">testinde her yatay doğru grafiği tek noktada keser).</text>\n  <text x="377" y="168" font-size="11.5" font-weight="bold" fill="#713f12">• Maksimum ve Minimum Değerler:</text>\n  <text x="387" y="186" font-size="10.5" fill="#334155">- Tanım kümesi ℝ ise: Maks / Min noktası YOKTUR.</text>\n  <text x="387" y="204" font-size="10.5" font-weight="bold" fill="#854d0e">- Tanım kümesi [m, n] kapalı aralığı ise: Uç</text>\n  <text x="387" y="220" font-size="10.5" font-weight="bold" fill="#854d0e">noktalarda g(m) ve g(n) maks/min değerleri verir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">SABİT DEĞİŞİM ORANI VE GERÇEK YAŞAM MODELLEMESİ</text>\n  <rect x="25" y="42" width="320" height="200" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="185" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">DEĞİŞİM ORANI (EĞİM = a)</text>\n  <text x="42" y="95" font-size="12" font-weight="bold" fill="#581c87">• Sabit Değişim Oranı Bağıntısı:</text>\n  <text x="185" y="122" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">a = Δy / Δx = [g(x₂) - g(x₁)] / (x₂ - x₁)</text>\n  <text x="42" y="152" font-size="11" fill="#334155">• Bağımsız değişken (x) 1 birim arttığında bağımlı</text>\n  <text x="52" y="169" font-size="11" fill="#334155">değişken g(x) her adımda sabit \'a\' kadar değişir.</text>\n  <text x="42" y="195" font-size="11.5" font-weight="bold" fill="#581c87">• a &gt; 0 → Artan Fonksiyon (Doğru sağa yatık)</text>\n  <text x="42" y="216" font-size="11.5" font-weight="bold" fill="#dc2626">• a &lt; 0 → Azalan Fonksiyon (Doğru sola yatık)</text>\n  <rect x="360" y="42" width="315" height="200" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="517" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#9a3412">GERÇEK YAŞAM MODELİ: g(x) = a·x + b</text>\n  <text x="377" y="95" font-size="11.5" font-weight="bold" fill="#7c2d12">• b (Sabit Terim / g(0)): Başlangıç miktarı</text>\n  <text x="387" y="112" font-size="10.5" fill="#334155">(Taksimetre açılış ücreti, fidanın ilk boyu, ilk su)</text>\n  <text x="377" y="138" font-size="11.5" font-weight="bold" fill="#7c2d12">• a (Eğim / Katsayı): Birim zamandaki değişim hızı</text>\n  <text x="387" y="155" font-size="10.5" fill="#334155">(Km başına ücret, aylık uzama, dakikada akan su)</text>\n  <rect x="377" y="172" width="280" height="54" rx="6" fill="#ffedd5"/>\n  <text x="517" y="192" text-anchor="middle" font-size="11" font-weight="bold" fill="#9a3412">Örnek: 450 L\'lik depodan dakikada 15 L su boşalırsa:</text>\n  <text x="517" y="212" text-anchor="middle" font-size="12" font-weight="bold" fill="#c2410c">Kalan Su: V(t) = 450 - 15t  (t ∈ [0, 30])</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
